import { readdirSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import {
  DEFAULT_ROUTE_TABLES,
  ROUTES_SCHEMA,
  globRegex,
  nearestPackage,
  property,
  routeLayout,
  routeSegments,
  tableBase,
} from '../project.mjs';

/** Where the generated file lives, relative to the project root, unless the rule is told otherwise. */
export const DEFAULT_ROUTE_PATHS_FILE = 'src/app/route-paths.ts';

/** How many added / removed paths a `stale` message names before it says how many more. */
const SHOWN = 5;

const SKIPPED_DIRS = new Set(['node_modules', 'dist', 'tmp', 'coverage']);

/** The directories a glob cannot reach outside of: its segments before the first wildcard. */
function globPrefix(glob) {
  const out = [];
  for (const seg of glob.split('/').slice(0, -1)) {
    if (/[*?[\]{}]/.test(seg)) break;
    out.push(seg);
  }
  return out.join('/');
}

/** Every project path under `root` matching one of the route table globs, first glob first. */
function routeTables(root, globs) {
  const found = [];
  const seen = new Set();
  for (const glob of globs) {
    const regex = globRegex(glob);
    const matches = [];
    const walk = (dir) => {
      let entries;
      try {
        entries = readdirSync(join(root, dir), { withFileTypes: true });
      } catch {
        return;
      }
      for (const entry of entries) {
        const path = dir ? `${dir}/${entry.name}` : entry.name;
        if (entry.isDirectory()) {
          if (!entry.name.startsWith('.') && !SKIPPED_DIRS.has(entry.name)) walk(path);
        } else if (regex.test(path) && !seen.has(path)) {
          seen.add(path);
          matches.push(path);
        }
      }
    };
    walk(globPrefix(glob));
    found.push(...matches.sort());
  }
  return found;
}

/** The AST of a file with the parser the app's config uses; throws when it does not parse. */
function parseFile(parser, filePath) {
  const code = readFileSync(filePath, 'utf8');
  const options = {
    ecmaVersion: 'latest',
    sourceType: 'module',
    filePath,
    range: true,
    loc: true,
  };
  if (typeof parser?.parseForESLint === 'function') {
    const result = parser.parseForESLint(code, options);
    return { ast: result.ast, keys: result.visitorKeys };
  }
  if (typeof parser?.parse === 'function') return { ast: parser.parse(code, options) };
  throw new Error('the configured parser has neither parseForESLint nor parse');
}

const NOT_CHILDREN = new Set(['parent', 'loc', 'range', 'tokens', 'comments']);

/**
 * Every navigable path one route table declares, mounted at `base`. The walk links `parent` on
 * its way down (a parser's AST has none), so the route walk can climb.
 */
function tablePaths(ast, keys, base) {
  const paths = [];
  const visit = (node) => {
    if (
      node.type === 'ObjectExpression' &&
      node.parent?.type === 'ArrayExpression' &&
      !property(node, 'redirectTo') &&
      ['component', 'loadComponent', 'children', 'loadChildren'].some((k) => property(node, k))
    ) {
      const segs = routeSegments(node);
      if (segs && !segs.includes('**')) paths.push([...base, ...segs].join('/'));
    }
    const childKeys = keys?.[node.type] ?? Object.keys(node);
    for (const key of childKeys) {
      if (NOT_CHILDREN.has(key)) continue;
      const value = node[key];
      for (const child of Array.isArray(value) ? value : [value]) {
        if (child && typeof child === 'object' && typeof child.type === 'string') {
          child.parent = node;
          visit(child);
        }
      }
    }
  };
  visit(ast);
  return paths;
}

const quote = (path) => `'${path.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;

/**
 * The generated file's text for `paths`: one member per line, kept that way under prettier (which
 * would join a short union onto one line) by a `prettier-ignore` on the alias.
 */
export function renderRoutePaths(paths, file = DEFAULT_ROUTE_PATHS_FILE) {
  return [
    '// Generated by the qits/route-paths lint rule from the route tables. Do not edit by hand.',
    `// Regenerate with: eslint --fix ${file}`,
    '// prettier-ignore',
    'export type RoutePath =',
    `${paths.map((p) => `  | ${quote(p)}`).join('\n')};`,
    '',
    "declare module '@qits/angular' {",
    '  interface QitsApp {',
    '    routePath: RoutePath;',
    '  }',
    '}',
    '',
  ].join('\n');
}

/** The paths a generated file lists today (the string members of its `RoutePath`). */
function listedPaths(text) {
  const union = /export\s+type\s+RoutePath\s*=([^;]*);/.exec(text);
  if (!union) return [];
  return [...union[1].matchAll(/'((?:[^'\\]|\\.)*)'|"((?:[^"\\]|\\.)*)"/g)].map((m) =>
    (m[1] ?? m[2]).replace(/\\(.)/g, '$1'),
  );
}

/** A path list for a message: quoted, `/`-rooted for readability, cut after SHOWN. */
function describe(paths) {
  if (paths.length === 0) return 'none';
  const shown = paths.slice(0, SHOWN).map((p) => `'/${p}'`);
  if (paths.length > SHOWN) shown.push(`and ${paths.length - SHOWN} more`);
  return shown.join(', ');
}

/**
 * The app's navigable paths as a type: `src/app/route-paths.ts` (option `file`) holds
 * `export type RoutePath = '' | 'projects' | …` and augments `@qits/angular`'s `QitsApp` with it,
 * generated from the route tables (`routeTables`, read from disk with the app's parser). A path is
 * listed for every route that renders something (`component`, `loadComponent`, `children`,
 * `loadChildren`), joined from the top of its table; a table under the routes directory is
 * mounted at its own directory. `''` is always listed; `**`, `redirectTo` routes and routes whose
 * path chain is not literal are not. The file is opt-in: create it (empty is enough) and run
 * `eslint --fix <file>` to generate it. On the generated file the rule reports `stale` when its
 * text differs, and `--fix` rewrites it; a missing file is not reported anywhere.
 */
export default {
  meta: {
    type: 'problem',
    fixable: 'code',
    docs: {
      description:
        "The generated route-paths file lists exactly the app's route table paths (eslint --fix regenerates it).",
    },
    schema: [
      {
        ...ROUTES_SCHEMA,
        properties: { ...ROUTES_SCHEMA.properties, file: { type: 'string', minLength: 1 } },
      },
    ],
    messages: {
      stale:
        "'{{file}}' is out of date with the route tables (added: {{added}}; removed: {{removed}}). Regenerate it with `eslint --fix {{file}}`.",
      unparsable: "Route table '{{table}}' could not be parsed to generate '{{file}}': {{error}}",
    },
  },
  create(context) {
    const options = context.options[0] ?? {};
    const file = (options.file ?? DEFAULT_ROUTE_PATHS_FILE).replace(/^\.\//, '');
    const layout = routeLayout(context);
    if (layout.file !== file) return {};
    const root = nearestPackage(layout.absolute)?.dir ?? context.cwd;
    const tables = routeTables(root, options.routeTables ?? DEFAULT_ROUTE_TABLES);

    return {
      Program(node) {
        const parser = context.languageOptions?.parser;
        const paths = new Set(['']);
        for (const table of tables) {
          let parsed;
          try {
            parsed = parseFile(parser, resolve(root, table));
          } catch (error) {
            context.report({
              node,
              loc: { line: 1, column: 0 },
              messageId: 'unparsable',
              data: { table, file, error: String(error?.message ?? error).split('\n')[0] },
            });
            return;
          }
          for (const path of tablePaths(parsed.ast, parsed.keys, tableBase(layout, table)))
            paths.add(path);
        }
        const sorted = [...paths].sort();
        const expected = renderRoutePaths(sorted, file);
        const actual = context.sourceCode.text;
        if (actual === expected) return;
        const listed = new Set(listedPaths(actual));
        context.report({
          node,
          loc: { line: 1, column: 0 },
          messageId: 'stale',
          data: {
            file,
            added: describe(sorted.filter((p) => !listed.has(p))),
            removed: describe([...listed].filter((p) => !paths.has(p)).sort()),
          },
          fix: (fixer) => fixer.replaceTextRange([0, actual.length], expected),
        });
      },
    };
  },
};
